// Écran d'accueil de l'app chauffeur (affiché seulement AVANT la connexion). Ne bloque jamais un chauffeur connecté.
(function () {
  try {
    var IMG = "data:image/jpeg;base64,";
    function visible(el) { return el && getComputedStyle(el).display !== "none" && el.offsetParent !== null; }
    function afficher() {
      var login = document.getElementById("ecran-login");
      if (!visible(login) || document.getElementById("tw-accueil-ch")) return;
      var st = document.createElement("style");
      st.textContent = "#tw-accueil-ch{position:fixed;inset:0;z-index:99999;background:linear-gradient(#f4f4f4,#e9e9e9 60%,#dcdcdc);display:flex;flex-direction:column;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;padding-top:env(safe-area-inset-top)}"
        + "#tw-accueil-ch .h{padding:70px 24px 0;text-align:center}#tw-accueil-ch .l{font-size:44px;font-weight:800;color:#0e1a2c;letter-spacing:1px}#tw-accueil-ch .l span{color:#1f9d55}"
        + "#tw-accueil-ch .s{margin-top:6px;font-size:16px;color:#3a4558;letter-spacing:3px;text-transform:uppercase}"
        + "#tw-accueil-ch .p{flex:1;background:url(" + IMG + ") center 55%/115% auto no-repeat;mix-blend-mode:multiply;-webkit-mask-image:radial-gradient(70% 60% at 50% 55%,#000 60%,transparent 100%);mask-image:radial-gradient(70% 60% at 50% 55%,#000 60%,transparent 100%)}"
        + "#tw-accueil-ch .b{padding:0 22px calc(40px + env(safe-area-inset-bottom))}#tw-accueil-ch button{width:100%;border:none;background:#0e1a2c;color:#fff;font-weight:700;font-size:18px;border-radius:30px;padding:17px;cursor:pointer}"
        + "#tw-accueil-ch .a{text-align:center;color:#6b7383;font-size:13px;margin-top:14px}";
      document.head.appendChild(st);
      var d = document.createElement("div");
      d.id = "tw-accueil-ch";
      d.innerHTML = '<div class="h"><div class="l">TAXI <span>WAL</span></div><div class="s">Espace chauffeurs</div></div><div class="p"></div>'
        + '<div class="b"><button type="button">Se connecter</button><div class="a">Un souci pour te connecter ? Appelle la centrale</div></div>';
      document.body.appendChild(d);
      d.querySelector("button").addEventListener("click", function () {
        d.remove();
        var e = document.getElementById("email"); if (e) { try { e.focus(); } catch (x) {} }
      });
      // Si la connexion se fait quand même (session retrouvée), l'écran disparaît tout seul
      var t = setInterval(function () { if (!visible(document.getElementById("ecran-login"))) { clearInterval(t); d.remove(); } }, 500);
    }
    // Attend que l'app ait vérifié la session (un chauffeur déjà connecté ne voit jamais cet écran)
    function lancer() { setTimeout(afficher, 1800); }
    if (document.readyState === "complete") lancer(); else window.addEventListener("load", lancer);
  } catch (e) {}
})();
